package io.github.diodeme.ji.workspace.local;

import io.github.diodeme.ji.agent.ToolDefinition;
import io.github.diodeme.ji.extension.ToolRetryContract;
import io.github.diodeme.ji.extension.WorkspaceProvider;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;

/** Built-in read/write/edit/shell definitions backed only by a Workspace capability. */
public final class WorkspaceTools {
    private WorkspaceTools() {}

    public static List<ToolDefinition> defaults(WorkspaceProvider workspace) {
        return List.of(read(workspace), write(workspace), edit(workspace), shell(workspace));
    }

    public static ToolDefinition read(WorkspaceProvider workspace) {
        return new ToolDefinition(schema("read", "Read file contents", Map.of(
                "path", property("string"), "offset", property("integer"), "limit", property("integer"))),
                ToolDefinition.PermissionMode.ASK, ToolRetryContract.READ_ONLY, false,
                (arguments, cancellation) -> {
                    String path = text(arguments, "path");
                    long offset = number(arguments, "offset", 1);
                    long limit = number(arguments, "limit", Integer.MAX_VALUE);
                    WorkspaceProvider.FileContent content = workspace.read(
                            workspace.resolve(path, WorkspaceProvider.Access.READ),
                            WorkspaceProvider.ReadOptions.text(offset, limit), cancellation);
                    Map<String, Object> details = new LinkedHashMap<>();
                    details.put("revision", content.revision());
                    details.put("totalLines", content.totalLines());
                    details.put("truncated", content.truncated());
                    if (content.truncated()) {
                        details.put("truncatedBy", content.truncatedBy());
                        details.put("nextOffset", content.nextOffset());
                    }
                    return new ToolDefinition.ToolResult(content.text(StandardCharsets.UTF_8), details);
                });
    }

    public static ToolDefinition write(WorkspaceProvider workspace) {
        return new ToolDefinition(schema("write", "Create or overwrite a file", Map.of(
                "path", property("string"), "content", property("string"),
                "expectedRevision", property("integer"))), ToolDefinition.PermissionMode.ASK,
                ToolRetryContract.NON_RETRYABLE, true, (arguments, cancellation) -> {
                    String path = text(arguments, "path");
                    byte[] content = text(arguments, "content").getBytes(StandardCharsets.UTF_8);
                    WorkspaceProvider.MutationResult result = workspace.write(
                            workspace.resolve(path, WorkspaceProvider.Access.WRITE), content,
                            optionalRevision(arguments), cancellation);
                    return new ToolDefinition.ToolResult(
                            "Successfully wrote " + content.length + " bytes to " + path,
                            Map.of("revision", result.revision(), "bytesWritten", result.bytesWritten()));
                });
    }

    public static ToolDefinition edit(WorkspaceProvider workspace) {
        return new ToolDefinition(schema("edit", "Edit a file with exact replacements", Map.of(
                "path", property("string"), "edits", property("array"),
                "expectedRevision", property("integer"))), ToolDefinition.PermissionMode.ASK,
                ToolRetryContract.NON_RETRYABLE, true, (arguments, cancellation) -> {
                    String path = text(arguments, "path");
                    long revision = number(arguments, "expectedRevision", -1);
                    if (revision < 0) throw new IllegalArgumentException("expectedRevision is required");
                    List<WorkspaceProvider.Replacement> replacements = replacements(arguments.get("edits"));
                    WorkspaceProvider.MutationResult result = workspace.edit(
                            workspace.resolve(path, WorkspaceProvider.Access.WRITE), replacements, revision, cancellation);
                    return new ToolDefinition.ToolResult(
                            "Successfully replaced " + replacements.size() + " block(s) in " + path + ".",
                            Map.of("revision", result.revision(), "bytesWritten", result.bytesWritten()));
                });
    }

    public static ToolDefinition shell(WorkspaceProvider workspace) {
        return new ToolDefinition(schema("shell", "Execute a structured process or explicit shell command", Map.of(
                "argv", property("array"), "command", property("string"), "cwd", property("string"),
                "env", property("object"), "timeoutSeconds", property("integer"))),
                ToolDefinition.PermissionMode.ASK, ToolRetryContract.NON_RETRYABLE, true,
                (arguments, cancellation) -> {
                    String cwdValue = arguments.get("cwd") instanceof String value ? value : ".";
                    WorkspaceProvider.Command command = command(arguments);
                    long timeout = number(arguments, "timeoutSeconds", 120);
                    @SuppressWarnings("unchecked")
                    Map<String, String> environment = arguments.get("env") instanceof Map<?, ?> values
                            ? stringMap(values) : Map.of();
                    WorkspaceProvider.ProcessResult result = workspace.execute(new WorkspaceProvider.ProcessRequest(
                            workspace.identity(), command,
                            workspace.resolve(cwdValue, WorkspaceProvider.Access.EXECUTE), environment,
                            Duration.ofSeconds(timeout)), cancellation);
                    String stdout = new String(result.stdout(), StandardCharsets.UTF_8);
                    String stderr = new String(result.stderr(), StandardCharsets.UTF_8);
                    String output = stdout + (stderr.isEmpty() ? "" : (stdout.isEmpty() ? "" : "\n") + stderr);
                    Map<String, Object> details = Map.of("exitCode", result.exitCode(),
                            "stdoutTruncated", result.stdoutTruncated(), "stderrTruncated", result.stderrTruncated());
                    if (result.exitCode() != 0) throw new IllegalStateException("shell exited with " + result.exitCode());
                    return new ToolDefinition.ToolResult(output.isEmpty() ? "(no output)" : output, details);
                });
    }

    private static io.github.diodeme.ji.ai.ToolSchema schema(
            String name, String description, Map<String, Object> properties) {
        return new io.github.diodeme.ji.ai.ToolSchema(name, description,
                Map.of("type", "object", "properties", properties));
    }

    private static Map<String, Object> property(String type) {
        return Map.of("type", type);
    }

    private static String text(Map<String, Object> arguments, String name) {
        Object value = arguments.get(name);
        if (!(value instanceof String text)) throw new IllegalArgumentException(name + " must be a string");
        return text;
    }

    private static long number(Map<String, Object> arguments, String name, long fallback) {
        Object value = arguments.get(name);
        if (value == null) return fallback;
        if (!(value instanceof Number number)) throw new IllegalArgumentException(name + " must be a number");
        return number.longValue();
    }

    private static OptionalLong optionalRevision(Map<String, Object> arguments) {
        Object value = arguments.get("expectedRevision");
        return value == null ? OptionalLong.empty() : OptionalLong.of(number(arguments, "expectedRevision", 0));
    }

    private static List<WorkspaceProvider.Replacement> replacements(Object value) {
        if (!(value instanceof List<?> values) || values.isEmpty()) {
            throw new IllegalArgumentException("edits must be a non-empty array");
        }
        var result = new ArrayList<WorkspaceProvider.Replacement>();
        for (Object item : values) {
            if (!(item instanceof Map<?, ?> map)) throw new IllegalArgumentException("each edit must be an object");
            result.add(new WorkspaceProvider.Replacement(String.valueOf(map.get("oldText")),
                    String.valueOf(map.get("newText"))));
        }
        return List.copyOf(result);
    }

    private static WorkspaceProvider.Command command(Map<String, Object> arguments) {
        Object argv = arguments.get("argv");
        if (argv instanceof List<?> values) {
            return new WorkspaceProvider.Command.Argv(values.stream().map(String::valueOf).toList());
        }
        return new WorkspaceProvider.Command.Shell(text(arguments, "command"));
    }

    private static Map<String, String> stringMap(Map<?, ?> values) {
        var result = new LinkedHashMap<String, String>();
        values.forEach((key, value) -> result.put(String.valueOf(key), String.valueOf(value)));
        return Map.copyOf(result);
    }
}
